/// <reference types="node" />
/*
 * Resolves the TypeGPU shaders in src/render/shaders.ts to WGSL and writes them, with the vertex buffer layouts, to
 * src/render/shaders.gen.ts. The renderer imports only the generated file, so the app neither ships TypeGPU nor spends
 * startup time resolving shaders (about 20 ms on the Android emulator). src/render/shaders.test.ts fails when the
 * generated file is stale.
 *
 *   npm run gen:shaders
 */
import { writeFileSync } from 'node:fs';
import { SHADERS, instanceLayout, meshVertexLayout, shaderCode } from '../src/render/shaders';

export function generate(): string {
  const wgsl = Object.entries(SHADERS).map(([id, pair]) => `  ${id}: ${JSON.stringify(shaderCode(pair))},`);
  return `// Generated by scripts/gen-shaders.ts from src/render/shaders.ts. Do not edit; rerun \`npm run gen:shaders\`.

export type ShaderId = ${Object.keys(SHADERS).map((id) => `'${id}'`).join(' | ')};

/** One WGSL module per pipeline, each with one vertex and one fragment entry point over the uniform block. */
export const WGSL: { readonly [K in ShaderId]: string } = {
${wgsl.join('\n')}
};

/** Interleaved position, normal, and color: MeshVertex in shaders.ts. */
export const MESH_VERTEX_LAYOUT: GPUVertexBufferLayout = ${JSON.stringify(meshVertexLayout.vertexLayout)};

/** One per drawn instance: Instance in shaders.ts. */
export const INSTANCE_LAYOUT: GPUVertexBufferLayout = ${JSON.stringify(instanceLayout.vertexLayout)};
`;
}

if (process.argv[1]?.endsWith('gen-shaders.ts')) {
  writeFileSync(new URL('../src/render/shaders.gen.ts', import.meta.url), generate());
  console.log('wrote src/render/shaders.gen.ts');
}
